-- C12 provider registries: one registry table for every
-- provider family (payments, email, storage, vcs, ai, cloud).
--
-- Before this migration each family kept its providers as a closed
-- enum plus 4-8 parallel `match` tables in code (display name, base
-- URLs, allowed hosts, capabilities, currencies, credentials shape).
-- Adding one provider meant a code change in 5+ places and an admin
-- could not do it at all. From here the definitions are DATA: this
-- table holds id, display name, base URLs, allowed hosts,
-- capabilities, currencies, credentials shape, models, and the
-- adapter that serves the provider. The runtime registry
-- (`unified_core::provider_registry`) is the in-memory view of this
-- table; `load_from_rows` is the hook a startup loader uses to
-- replace the embedded seeds with these rows.
--
-- Seed rows below are GENERATED from
-- crates/unified-core/provider_registry_seed.json (the single source
-- of truth) - see docs/integration/c12_generate_registry_seed_sql.py.
-- Do not hand-edit the INSERT block; regenerate it instead.
-- `ON CONFLICT ... DO NOTHING` keeps the migration idempotent and
-- never overwrites an admin-edited row on re-run.
--
-- The in-memory DashMap / OnceLock registries remain authoritative
-- at runtime until the DB-row startup loader lands (follow-up, see
-- docs/integration/INTEGRATION_NOTES_C12.md); this table is the
-- durable record and the admin surface writes here first.

CREATE TABLE IF NOT EXISTS provider_registry_definitions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    family TEXT NOT NULL
        CHECK (family IN ('payments', 'email', 'storage', 'vcs', 'ai', 'cloud')),
    provider_id TEXT NOT NULL
        CHECK (provider_id ~ '^[a-z0-9][a-z0-9_-]{0,63}$'),
    display_name TEXT NOT NULL CHECK (char_length(display_name) > 0),
    base_url TEXT,
    sandbox_base_url TEXT,
    api_style TEXT,
    auth_scheme TEXT,
    webhook_signature_header TEXT,
    allowed_hosts JSONB NOT NULL DEFAULT '[]'::jsonb,
    capabilities JSONB NOT NULL DEFAULT '{}'::jsonb,
    currencies JSONB NOT NULL DEFAULT '[]'::jsonb,
    credentials_shape JSONB NOT NULL DEFAULT '[]'::jsonb,
    models JSONB NOT NULL DEFAULT '[]'::jsonb,
    default_model TEXT,
    adapter_kind TEXT NOT NULL CHECK (char_length(adapter_kind) > 0),
    needs_endpoint BOOLEAN NOT NULL DEFAULT FALSE,
    needs_delegate BOOLEAN NOT NULL DEFAULT FALSE,
    notes TEXT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    builtin BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (family, provider_id)
);

CREATE INDEX IF NOT EXISTS idx_provider_registry_family
    ON provider_registry_definitions (family);
CREATE INDEX IF NOT EXISTS idx_provider_registry_enabled
    ON provider_registry_definitions (family, enabled);
CREATE INDEX IF NOT EXISTS idx_provider_registry_adapter_kind
    ON provider_registry_definitions (adapter_kind);

-- Seed: the 50 built-in definitions (payments 12, email 9,
-- storage 5, vcs 3, ai 4, cloud 17). Generated - see header.
-- Seed rows generated from crates/unified-core/provider_registry_seed.json (version 1, 50 providers). Do not hand-edit: regenerate instead.
