INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('payments', 'card', 'Credit / Debit Card', NULL, NULL, NULL, NULL, NULL, '[]', '{"authorize":true,"capture":true,"charge":true,"refund":true,"void":true,"subscriptions":true,"payouts":false,"3ds":true,"webhooks":true,"subscriptions_are_local_schedule":true}', '["USD","EUR","GBP","IDR","SGD","MYR","PHP","THB","AED","SAR","AUD","CAD","JPY","CHF"]', '[{"name":"api_key","label":"Processor API key","type":"password","required":true,"secret":true,"applies_to":"both","description":"API key for the card processor behind the endpoint. Sent as a Bearer token unless the processor expects an X-Api-Key header."},{"name":"webhook_secret","label":"Webhook secret","type":"password","required":false,"secret":true,"applies_to":"both","description":"Shared secret for HMAC-SHA256 webhook verification (X-Signature header)."},{"name":"merchant_id","label":"Merchant ID","type":"text","required":false,"secret":false,"applies_to":"both","description":"Merchant identifier sent to the processor when it requires one."}]', '[]', NULL, 'generic_card', TRUE, FALSE, 'User-supplied processor endpoint; validated as an https URL with a host and no embedded credentials.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
