INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('payments', 'custom', 'Custom Provider', NULL, NULL, NULL, NULL, NULL, '[]', '{"authorize":true,"capture":true,"charge":true,"refund":true,"void":true,"subscriptions":true,"payouts":true,"3ds":false,"webhooks":true,"subscriptions_are_local_schedule":false}', '["USD","EUR","GBP","IDR","SGD"]', '[{"name":"api_key","label":"API key","type":"password","required":false,"secret":true,"applies_to":"both","description":"API key sent according to the custom auth type (Bearer, header, or query)."},{"name":"secret_key","label":"Secret / signing key","type":"password","required":false,"secret":true,"applies_to":"both","description":"Secret used for HMAC-SHA256 request signing and webhook verification when the auth type is hmac_sha256."},{"name":"username","label":"Username","type":"text","required":false,"secret":false,"applies_to":"both","description":"Username for Basic auth when the auth type is basic."},{"name":"password","label":"Password","type":"password","required":false,"secret":true,"applies_to":"both","description":"Password for Basic auth when the auth type is basic."},{"name":"webhook_secret","label":"Webhook secret","type":"password","required":false,"secret":true,"applies_to":"both","description":"Shared secret for HMAC-SHA256 webhook verification when the auth type is hmac_sha256."}]', '[]', NULL, 'custom', TRUE, FALSE, 'Config-driven generic adapter (CustomGatewayConfig). This is the adapter a newly registered provider uses when it has no native adapter code.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('payments', 'bank_transfer', 'Bank Transfer (Manual Verification)', NULL, NULL, NULL, NULL, NULL, '[]', '{"authorize":true,"capture":false,"charge":true,"refund":true,"void":true,"subscriptions":false,"payouts":false,"3ds":false,"webhooks":false,"subscriptions_are_local_schedule":false}', '["USD","EUR","GBP","IDR","SGD","MYR","PHP","THB","AUD","CAD","JPY","CHF","AED","SAR"]', '[{"name":"amount_tolerance_minor","label":"Amount tolerance (minor units)","type":"text","required":false,"secret":false,"applies_to":"both","description":"Maximum minor-unit difference accepted between the transferred amount and the order total before the proof is flagged as a mismatch."},{"name":"proof_expiry_days","label":"Proof expiry (days)","type":"text","required":false,"secret":false,"applies_to":"both","description":"Days after which an unsubmitted proof request expires."}]', '[]', NULL, 'manual', FALSE, FALSE, 'No provider API exists: verification is manual. A charge only opens a pending manual verification; the administrator approval is the capture.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'mailchimp', 'Mailchimp Transactional (Mandrill)', 'https://mandrillapp.com', NULL, NULL, NULL, NULL, '["mandrillapp.com"]', '{"transactional":true,"bulk":true,"templates":true,"webhooks":true,"tracking":true,"sandbox":false}', '[]', '[{"name":"api_key","label":"Mandrill API key","type":"password","required":true,"secret":true,"description":"API key from the Mandrill dashboard (Settings > API Keys)."},{"name":"webhook_url","label":"Public webhook URL","type":"url","required":false,"secret":false,"placeholder":"https://example.com/api/v1/newsletter/webhooks/mailchimp","description":"Exact public URL of the webhook receiver; Mandrill signs webhooks with this URL."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'mailchimp', FALSE, FALSE, 'Sending domains must be verified in Mandrill (Settings > Sending Domains); add SPF and DKIM records for the domain before sending bulk mail. Mandrill webhooks are verified with HMAC-SHA1 over the webhook URL plus the sorted POST parameters, using the webhook key. Set webhook_url to the exact public webhook URL.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'brevo', 'Brevo (Sendinblue)', 'https://api.brevo.com', NULL, NULL, NULL, NULL, '["api.brevo.com"]', '{"transactional":true,"bulk":true,"templates":true,"webhooks":true,"tracking":true,"sandbox":false}', '[]', '[{"name":"api_key","label":"Brevo API key","type":"password","required":true,"secret":true,"description":"API key from Brevo (Settings > SMTP & API > API Keys), version 3."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'brevo', FALSE, FALSE, 'Verify the sender domain in Brevo (Senders & IP > Domains) and add the SPF and DKIM records Brevo shows; unverified senders are limited. Brevo sends no signature; set a webhook_secret on the connection and Brevo must send it back as the X-Webhook-Secret header (configure it in the Brevo webhook URL as a custom header).', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'sendgrid', 'SendGrid', 'https://api.sendgrid.com', NULL, NULL, NULL, NULL, '["api.sendgrid.com"]', '{"transactional":true,"bulk":true,"templates":true,"webhooks":true,"tracking":true,"sandbox":true}', '[]', '[{"name":"api_key","label":"SendGrid API key","type":"password","required":true,"secret":true,"description":"API key from SendGrid (Settings > API Keys) with Mail Send permission."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'sendgrid', FALSE, FALSE, 'Authenticate the sender domain in SendGrid (Settings > Sender Authentication) with SPF and DKIM; single sender verification is enough for low volume. SendGrid Event Webhook signatures use ECDSA verification, which this module does not implement; set a webhook_secret on the connection and require it as the X-Webhook-Secret header instead.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'mailgun', 'Mailgun', 'https://api.mailgun.net', NULL, NULL, NULL, NULL, '["api.mailgun.net","api.eu.mailgun.net"]', '{"transactional":true,"bulk":true,"templates":true,"webhooks":true,"tracking":true,"sandbox":true}', '[]', '[{"name":"api_key","label":"Mailgun API key","type":"password","required":true,"secret":true,"description":"Private API key from Mailgun (Settings > API Keys)."},{"name":"domain","label":"Mailgun domain","type":"text","required":true,"secret":false,"placeholder":"mg.example.com","description":"Verified sending domain in Mailgun."},{"name":"region","label":"Region","type":"select","required":false,"secret":false,"placeholder":"us","description":"us (api.mailgun.net) or eu (api.eu.mailgun.net)."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'mailgun', FALSE, FALSE, 'Add and verify the domain in Mailgun (Sending > Domains) with the SPF and DKIM TXT records; sandbox domains only deliver to authorized recipients. Mailgun webhooks are verified with HMAC-SHA256 over timestamp + token, using the webhook signing key (webhook_secret).', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'postmark', 'Postmark', 'https://api.postmarkapp.com', NULL, NULL, NULL, NULL, '["api.postmarkapp.com"]', '{"transactional":true,"bulk":false,"templates":true,"webhooks":true,"tracking":true,"sandbox":false}', '[]', '[{"name":"api_key","label":"Postmark server token","type":"password","required":true,"secret":true,"description":"Server API token from Postmark (Servers > API Tokens)."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'postmark', FALSE, FALSE, 'Verify the sender signature (Sender Signatures) or the whole domain with DKIM in Postmark; every From address must be verified. Postmark sends no signature; set a webhook_secret on the connection and require it as the X-Webhook-Secret header (Postmark supports basic auth on the webhook URL as an alternative).', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'ses', 'Amazon SES', NULL, NULL, NULL, NULL, NULL, '[]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":true,"tracking":true,"sandbox":false}', '[]', '[{"name":"access_key_id","label":"AWS access key id","type":"text","required":true,"secret":false,"description":"IAM access key with ses:SendEmail permission."},{"name":"secret_access_key","label":"AWS secret access key","type":"password","required":true,"secret":true,"description":"IAM secret access key."},{"name":"region","label":"AWS region","type":"text","required":true,"secret":false,"placeholder":"us-east-1","description":"SES region, for example us-east-1 or eu-west-1."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'ses', FALSE, FALSE, 'Verify the sender identity (email address or domain) in SES; new accounts are in the SES sandbox and can only send to verified addresses until production access is granted. SES endpoints are per-region (email.<region>.amazonaws.com). SES delivers events through SNS, whose signatures need RSA certificate verification, which this module does not implement; set a webhook_secret on the connection and require it as the X-Webhook-Secret header instead.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'resend', 'Resend', 'https://api.resend.com', NULL, NULL, NULL, NULL, '["api.resend.com"]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":true,"tracking":true,"sandbox":false}', '[]', '[{"name":"api_key","label":"Resend API key","type":"password","required":true,"secret":true,"description":"API key from Resend (API Keys)."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'resend', FALSE, FALSE, 'Verify the sending domain in Resend (Domains) with SPF and DKIM; unverified accounts can only send to the account owner address. Resend webhooks are Svix-signed and verified with HMAC-SHA256 over the svix id, timestamp and body, using the webhook signing secret (webhook_secret).', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'sparkpost', 'SparkPost', 'https://api.sparkpost.com', NULL, NULL, NULL, NULL, '["api.sparkpost.com","api.eu.sparkpost.com"]', '{"transactional":true,"bulk":true,"templates":true,"webhooks":true,"tracking":true,"sandbox":false}', '[]', '[{"name":"api_key","label":"SparkPost API key","type":"password","required":true,"secret":true,"description":"API key from SparkPost (Account > API Keys) with Transmissions: Read/Write."},{"name":"region","label":"Region","type":"select","required":false,"secret":false,"placeholder":"us","description":"us (api.sparkpost.com) or eu (api.eu.sparkpost.com)."},{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own. Must be verified with the provider."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'sparkpost', FALSE, FALSE, 'Verify the sending domain in SparkPost (Account > Sending Domains) with SPF and DKIM records. SparkPost sends no signature; set a webhook_secret on the connection and require it as the X-Webhook-Secret header.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'smtp', 'SMTP (via Mail Manager)', NULL, NULL, NULL, NULL, NULL, '[]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"sender_email","label":"Sender email override","type":"email","required":false,"secret":false,"placeholder":"news@example.com","description":"Optional From override for the Mail Manager SMTP settings; empty means the SMTP settings apply."},{"name":"webhook_secret","label":"Webhook secret / signing key","type":"password","required":false,"secret":true,"description":"Secret used to verify incoming webhooks from this provider (see the webhook notes for the kind)."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'smtp', FALSE, FALSE, 'Delivery uses the Mail Manager SMTP settings; the From domain should have SPF and DKIM records for the SMTP host. SMTP has no webhooks; bounce and complaint handling is not available for this provider.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('storage', 'local', 'Local Filesystem', NULL, NULL, NULL, NULL, NULL, '[]', '{"upload":true,"download":true,"delete":true,"signed_url":true,"list":true,"test_connection":true}', '[]', '[{"name":"base_dir","label":"Base directory","type":"text","required":false,"secret":false,"placeholder":"data/storage","description":"Base directory for stored files. Defaults to data/storage."}]', '[]', NULL, 'local', FALSE, FALSE, 'Files under a configured base directory. Supports listing objects.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('storage', 's3', 'Amazon S3', NULL, NULL, NULL, NULL, NULL, '[]', '{"upload":true,"download":true,"delete":true,"signed_url":true,"list":false,"test_connection":true}', '[]', '[{"name":"endpoint","label":"Endpoint URL","type":"url","required":false,"secret":false,"description":"S3 endpoint URL. Empty means the default AWS endpoint for the region."},{"name":"region","label":"Region","type":"text","required":true,"secret":false,"placeholder":"us-east-1","description":"AWS region of the bucket."},{"name":"bucket","label":"Bucket","type":"text","required":true,"secret":false,"description":"S3 bucket name."},{"name":"access_key","label":"Access key","type":"text","required":true,"secret":false,"description":"AWS access key id."},{"name":"secret_key","label":"Secret key","type":"password","required":true,"secret":true,"description":"AWS secret access key."}]', '[]', NULL, 's3', FALSE, FALSE, 'AWS S3, SigV4-signed requests. The endpoint host must be allowlisted; listing objects is not supported by this provider.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('storage', 'r2', 'Cloudflare R2', NULL, NULL, NULL, NULL, NULL, '[]', '{"upload":true,"download":true,"delete":true,"signed_url":true,"list":false,"test_connection":true}', '[]', '[{"name":"endpoint","label":"Endpoint URL","type":"url","required":true,"secret":false,"description":"R2 endpoint URL (https://<account-id>.r2.cloudflarestorage.com)."},{"name":"region","label":"Region","type":"text","required":false,"secret":false,"placeholder":"auto","description":"Region; auto for R2."},{"name":"bucket","label":"Bucket","type":"text","required":true,"secret":false,"description":"R2 bucket name."},{"name":"access_key","label":"Access key","type":"text","required":true,"secret":false,"description":"R2 access key id."},{"name":"secret_key","label":"Secret key","type":"password","required":true,"secret":true,"description":"R2 secret access key."}]', '[]', NULL, 'r2', FALSE, FALSE, 'Cloudflare R2, S3-compatible; reuses the S3 signing code with a custom endpoint. The endpoint host must be allowlisted; listing objects is not supported by this provider.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('storage', 'google_drive', 'Google Drive', 'https://www.googleapis.com', NULL, NULL, NULL, NULL, '["www.googleapis.com","oauth2.googleapis.com"]', '{"upload":true,"download":true,"delete":true,"signed_url":true,"list":false,"test_connection":true}', '[]', '[{"name":"client_id","label":"OAuth2 client id","type":"text","required":true,"secret":false,"description":"Google OAuth2 client id (drive.file scope)."},{"name":"client_secret","label":"OAuth2 client secret","type":"password","required":true,"secret":true,"description":"Google OAuth2 client secret."},{"name":"refresh_token","label":"Refresh token","type":"password","required":true,"secret":true,"description":"OAuth2 refresh token."},{"name":"access_token","label":"Access token","type":"password","required":false,"secret":true,"description":"OAuth2 access token (refreshed automatically when empty)."},{"name":"token_url","label":"Token endpoint","type":"url","required":false,"secret":false,"description":"OAuth2 token endpoint. Empty means the default Google endpoint."}]', '[]', NULL, 'google_drive', FALSE, FALSE, 'Google Drive (drive.file scope) with an OAuth2 access token and a refresh-token flow. Upload returns the Drive file id as the storage key.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('storage', 'sftp', 'SFTP', NULL, NULL, NULL, NULL, NULL, '[]', '{"upload":true,"download":true,"delete":true,"signed_url":false,"list":true,"test_connection":true}', '[]', '[{"name":"sftp_host","label":"SFTP host","type":"text","required":true,"secret":false,"description":"SFTP host. Must be allowlisted."},{"name":"sftp_port","label":"SFTP port","type":"text","required":false,"secret":false,"placeholder":"22","description":"SFTP port. Empty means the default SSH port 22."},{"name":"sftp_username","label":"Username","type":"text","required":true,"secret":false,"description":"SFTP username."},{"name":"sftp_auth_kind","label":"Auth kind","type":"select","required":true,"secret":false,"placeholder":"keyfile","description":"keyfile or password."},{"name":"sftp_keyfile","label":"Private-key file path","type":"text","required":false,"secret":false,"description":"Private-key file path (keyfile auth only). Only the path is stored, never the key material."},{"name":"sftp_password","label":"Password","type":"password","required":false,"secret":true,"description":"SFTP password (password auth only)."},{"name":"sftp_base_path","label":"Remote base directory","type":"text","required":false,"secret":false,"description":"SFTP remote base directory. Empty means the remote home directory."}]', '[]', NULL, 'sftp', FALSE, FALSE, 'SFTP remote filesystem. Supports listing objects; signed URLs are not supported.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('vcs', 'github', 'GitHub', 'https://api.github.com', NULL, 'github', 'bearer', 'x-hub-signature-256', '["api.github.com"]', '{"releases":true,"tags":true,"webhooks":true}', '[]', '[{"name":"token","label":"Personal access token","type":"password","required":true,"secret":true,"description":"GitHub personal access token (Bearer)."},{"name":"webhook_secret","label":"Webhook secret","type":"password","required":false,"secret":true,"description":"Shared secret for webhook signature verification."},{"name":"api_base_override","label":"API base URL override","type":"url","required":false,"secret":false,"description":"Override for GitHub Enterprise Server API base URL."}]', '[]', NULL, 'github', FALSE, FALSE, NULL, TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('vcs', 'gitlab', 'GitLab', 'https://gitlab.com/api/v4', NULL, 'gitlab', 'private-token', 'x-gitlab-token', '["gitlab.com"]', '{"releases":true,"tags":true,"webhooks":true}', '[]', '[{"name":"token","label":"Personal access token","type":"password","required":true,"secret":true,"description":"GitLab personal access token (Private-Token header)."},{"name":"webhook_secret","label":"Webhook secret","type":"password","required":false,"secret":true,"description":"Shared secret for webhook verification."},{"name":"api_base_override","label":"API base URL override","type":"url","required":false,"secret":false,"description":"Override for a self-hosted GitLab instance API base URL."},{"name":"gitlab_hosts","label":"Self-hosted GitLab hosts","type":"text","required":false,"secret":false,"description":"Additional self-hosted GitLab instance hosts (comma separated)."}]', '[]', NULL, 'gitlab', FALSE, FALSE, 'Self-hosted instances use https://<host>/api/v4.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('vcs', 'bitbucket', 'Bitbucket', 'https://api.bitbucket.org/2.0', NULL, 'bitbucket', 'bearer', 'x-webhook-secret', '["api.bitbucket.org"]', '{"releases":true,"tags":true,"webhooks":true}', '[]', '[{"name":"token","label":"Access token","type":"password","required":true,"secret":true,"description":"Bitbucket access token (Bearer)."},{"name":"webhook_secret","label":"Webhook secret","type":"password","required":false,"secret":true,"description":"Shared secret checked in the X-Webhook-Secret header; Bitbucket provides no signature scheme."},{"name":"api_base_override","label":"API base URL override","type":"url","required":false,"secret":false,"description":"Override for the Bitbucket API base URL."}]', '[]', NULL, 'bitbucket', FALSE, FALSE, 'Bitbucket has no releases API; tags are the release list.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('ai', 'anthropic', 'Anthropic (Claude)', 'https://api.anthropic.com', NULL, NULL, NULL, NULL, '["api.anthropic.com"]', '{"key_required":true,"chat":true}', '[]', '[{"name":"api_key","label":"API key","type":"password","required":true,"secret":true,"description":"Anthropic API key."},{"name":"model","label":"Model","type":"text","required":false,"secret":false,"placeholder":"claude-sonnet-4-20250514","description":"Model id. Empty means the provider default model."},{"name":"rate_limit_per_minute","label":"Calls per minute","type":"text","required":false,"secret":false,"description":"Calls allowed per minute for this key (rate limit bucket)."}]', '["claude-sonnet-4-20250514"]', 'claude-sonnet-4-20250514', 'anthropic', FALSE, FALSE, NULL, TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('ai', 'openai', 'OpenAI (GPT)', 'https://api.openai.com/v1', NULL, NULL, NULL, NULL, '["api.openai.com"]', '{"key_required":true,"chat":true}', '[]', '[{"name":"api_key","label":"API key","type":"password","required":true,"secret":true,"description":"OpenAI API key."},{"name":"model","label":"Model","type":"text","required":false,"secret":false,"placeholder":"gpt-4o-mini","description":"Model id. Empty means the provider default model."},{"name":"rate_limit_per_minute","label":"Calls per minute","type":"text","required":false,"secret":false,"description":"Calls allowed per minute for this key (rate limit bucket)."}]', '["gpt-4o-mini"]', 'gpt-4o-mini', 'openai_compatible', FALSE, FALSE, NULL, TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('ai', 'openai_compatible', 'OpenAI-compatible endpoint', NULL, NULL, NULL, NULL, NULL, '[]', '{"key_required":true,"chat":true}', '[]', '[{"name":"api_key","label":"API key","type":"password","required":true,"secret":true,"description":"API key for the compatible endpoint."},{"name":"base_url","label":"Base URL","type":"url","required":true,"secret":false,"description":"Base URL of the OpenAI-compatible API endpoint."},{"name":"model","label":"Model","type":"text","required":true,"secret":false,"description":"Model id served by the endpoint (no default)."},{"name":"rate_limit_per_minute","label":"Calls per minute","type":"text","required":false,"secret":false,"description":"Calls allowed per minute for this key (rate limit bucket)."}]', '[]', NULL, 'openai_compatible', FALSE, FALSE, 'No fixed base URL or default model: the admin supplies both.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('ai', 'local', 'Local / bring-your-own endpoint', NULL, NULL, NULL, NULL, NULL, '[]', '{"key_required":false,"chat":true}', '[]', '[{"name":"api_key","label":"API key","type":"password","required":false,"secret":true,"description":"API key for the local endpoint, when it requires one. A local endpoint may run without one."},{"name":"base_url","label":"Base URL","type":"url","required":true,"secret":false,"description":"Base URL of the local model endpoint."},{"name":"model","label":"Model","type":"text","required":true,"secret":false,"description":"Model id served by the endpoint (no default)."},{"name":"rate_limit_per_minute","label":"Calls per minute","type":"text","required":false,"secret":false,"description":"Calls allowed per minute for this key (rate limit bucket)."}]', '[]', NULL, 'openai_compatible', FALSE, FALSE, 'No fixed base URL or default model: the admin supplies both. A local endpoint may run without an API key.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('cloud', 'hetzner', 'Hetzner Cloud', 'https://api.hetzner.cloud', NULL, NULL, NULL, NULL, '["api.hetzner.cloud"]', '{"create":true,"scale":true,"delete":true,"containers":false,"start_stop":false}', '[]', '[{"name":"api_token","label":"API token","type":"password","required":true,"secret":true,"description":"Hetzner Cloud API token."},{"name":"region","label":"Location","type":"text","required":false,"secret":false,"description":"Hetzner location (for example fsn1, nbg1, hel1)."}]', '[]', NULL, 'hetzner', FALSE, FALSE, NULL, TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('cloud', 'ovh', 'OVHcloud', 'https://api.ovh.com', NULL, NULL, NULL, NULL, '["api.ovh.com","eu.api.ovh.com"]', '{"create":true,"scale":true,"delete":true,"containers":false,"start_stop":false}', '[]', '[{"name":"application_key","label":"Application key","type":"text","required":true,"secret":false,"description":"OVH application key."},{"name":"application_secret","label":"Application secret","type":"password","required":true,"secret":true,"description":"OVH application secret."},{"name":"consumer_key","label":"Consumer key","type":"text","required":true,"secret":false,"description":"OVH consumer key."},{"name":"project_id","label":"Cloud project id","type":"text","required":true,"secret":false,"description":"OVH cloud project service name."},{"name":"region","label":"Region","type":"text","required":false,"secret":false,"description":"OVH region."}]', '[]', NULL, 'ovh', FALSE, FALSE, NULL, TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('cloud', 'tencent', 'Tencent Cloud CVM', 'https://cvm.tencentcloudapi.com', NULL, NULL, NULL, NULL, '["cvm.tencentcloudapi.com"]', '{"create":false,"scale":false,"delete":false,"containers":false,"start_stop":false}', '[]', '[{"name":"access_key_id","label":"Secret id","type":"text","required":true,"secret":false,"description":"Tencent Cloud secret id."},{"name":"secret_access_key","label":"Secret key","type":"password","required":true,"secret":true,"description":"Tencent Cloud secret key."},{"name":"region","label":"Region","type":"text","required":true,"secret":false,"description":"Tencent Cloud region."}]', '[]', NULL, 'tencent', FALSE, FALSE, 'Read-only adapter: inventory only, no create / scale / delete.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('cloud', 'huawei', 'Huawei Cloud ECS', NULL, NULL, NULL, NULL, NULL, '[]', '{"create":false,"scale":false,"delete":false,"containers":false,"start_stop":false}', '[]', '[{"name":"access_key_id","label":"Access key","type":"text","required":false,"secret":false,"description":"Huawei Cloud access key (either access key + secret key, or username + password)."},{"name":"secret_access_key","label":"Secret key","type":"password","required":false,"secret":true,"description":"Huawei Cloud secret key."},{"name":"username","label":"IAM username","type":"text","required":false,"secret":false,"description":"Huawei IAM username (either username + password, or access key + secret key)."},{"name":"password","label":"IAM password","type":"password","required":false,"secret":true,"description":"Huawei IAM password."},{"name":"region","label":"Region","type":"text","required":true,"secret":false,"description":"Huawei Cloud region (lowercase letters, digits and hyphens only, for example cn-north-4)."},{"name":"project_id","label":"Project id","type":"text","required":false,"secret":false,"description":"Huawei Cloud project id (resolved from the IAM token when empty)."}]', '[]', NULL, 'huawei', FALSE, FALSE, 'Endpoints are per-region (iam.<region>.myhuaweicloud.com, ecs.<region>.myhuaweicloud.com); validated by the Huawei adapter. Read-only adapter: inventory only.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('cloud', 'aws', 'AWS EC2', NULL, NULL, NULL, NULL, NULL, '[]', '{"create":false,"scale":false,"delete":false,"containers":false,"start_stop":false}', '[]', '[{"name":"access_key_id","label":"Access key id","type":"text","required":true,"secret":false,"description":"AWS access key id."},{"name":"secret_access_key","label":"Secret access key","type":"password","required":true,"secret":true,"description":"AWS secret access key."},{"name":"region","label":"Region","type":"text","required":true,"secret":false,"description":"AWS region."}]', '[]', NULL, 'aws', FALSE, FALSE, 'EC2 endpoints are per-region (ec2.<region>.amazonaws.com); validated by the AWS adapter. Read-only adapter: inventory only.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
