INSERT INTO provider_registry_definitions (family, provider_id, display_name, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('cloud', 'virtualizor', 'Virtualizor', NULL, NULL, NULL, NULL, NULL, '[]', '{"create":true,"scale":true,"delete":true,"containers":false,"start_stop":true}', '[]', '[{"name":"api_token","label":"API key","type":"password","required":true,"secret":true,"description":"Virtualizor API key."},{"name":"password","label":"API password","type":"password","required":true,"secret":true,"description":"Virtualizor API password."},{"name":"endpoint","label":"Panel URL","type":"url","required":true,"secret":false,"description":"Virtualizor panel URL."}]', '[]', NULL, 'virtualizor', FALSE, FALSE, 'User-supplied panel endpoint; validated as an http(s) URL with a host and no embedded credentials.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
